# Let's analyze the differences character by character
print("\nCharacter-by-character analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"'{inp}' -> '{out}':")
    if len(inp) == len(out):
        for j in range(len(inp)):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
    else:
        print(f"  Length changed from {len(inp)} to {len(out)}")
    print()

